-- WIN-BACK INTELLIGENCE FOR OPEN SM RENEWALS
-- Generated: 2026-03-12 14:32
-- Layer 1: CRM Enrichment (lifetime spend, ticket types, last email sentiment)
-- Layer 2: AI Win-Back Strategy (Cortex COMPLETE)
-- =============================================================================

USE WAREHOUSE TBRDP_DW_CORTEX_XS_WH;

-- STEP 1: Stage the 907 open renewal accounts
CREATE OR REPLACE TEMPORARY TABLE TBRDP_DW_PROD.IM_RPT.TMP_OPEN_RENEWALS (
    account_id VARCHAR,
    contact_name VARCHAR,
    account_name VARCHAR,
    renewal_amount NUMBER,
    current_stage VARCHAR,
    current_rep VARCHAR,
    objection_history VARCHAR,
    activity_count NUMBER,
    likelihood FLOAT,
    notes VARCHAR,
    is_business BOOLEAN
);

-- Batch 1

-- Batch 2

-- Batch 3

-- Batch 4

-- Batch 5

-- STEP 2: Enrich with CRM data (Layer 1)
-- Joins: T_CUSTOMER_360 (lifetime spend, ticket types) + T_EMAIL_ANALYTICS (last email sentiment)
CREATE OR REPLACE TEMPORARY TABLE TBRDP_DW_PROD.IM_RPT.TMP_RENEWAL_ENRICHED AS
SELECT
    r.*,
    c360.TOTAL_TICKET_REVENUE AS lifetime_spend,
    c360.TICKET_TYPES_PURCHASED AS ticket_types,
    c360.SEASONS_PURCHASED AS seasons_active,
    c360.REVENUE_TIER,
    last_email.SENTIMENT_CATEGORY AS last_email_sentiment
FROM TBRDP_DW_PROD.IM_RPT.TMP_OPEN_RENEWALS r
LEFT JOIN TBRDP_DW_PROD.IM_RPT.T_CUSTOMER_360 c360
    ON r.account_id = c360.SF_ACCOUNT_ID
LEFT JOIN (
    SELECT ACCOUNT_ID, SENTIMENT_CATEGORY,
           ROW_NUMBER() OVER (PARTITION BY ACCOUNT_ID ORDER BY MESSAGE_DATE DESC) AS rn
    FROM TBRDP_DW_PROD.IM_RPT.T_EMAIL_ANALYTICS
    WHERE SENTIMENT_CATEGORY IS NOT NULL
) last_email ON r.account_id = last_email.ACCOUNT_ID AND last_email.rn = 1;

-- STEP 3: Business Intelligence (Layer 3)
-- Web-researched intel for 23 business accounts, joined by account_name
CREATE OR REPLACE TEMPORARY TABLE TBRDP_DW_PROD.IM_RPT.TMP_BUSINESS_INTEL (
    company_name VARCHAR,
    business_intel VARCHAR
);


-- STEP 4: Generate AI win-back strategy (Layers 1+2+3 combined)
-- Uses Cortex COMPLETE with llama3.1-70b (~$2-5 estimated cost for 905 accounts)
-- Output: account_id, contact_name, CRM enrichment, business intel, AI recommendation
SELECT
    e.account_id,
    e.contact_name,
    e.account_name,
    e.renewal_amount,
    e.current_stage,
    e.current_rep,
    e.objection_history,
    e.activity_count,
    e.likelihood,
    e.notes,
    e.is_business,
    -- Layer 1: CRM Enrichment
    e.lifetime_spend,
    e.ticket_types,
    e.seasons_active,
    e.REVENUE_TIER,
    e.last_email_sentiment,
    -- Layer 3: Business Intelligence (for reference)
    bi.business_intel,
    -- Layer 2: AI Win-Back Strategy (informed by all layers)
    SNOWFLAKE.CORTEX.COMPLETE(
        'llama3.1-70b',
        'You are a senior sales strategist for the Tampa Bay Rays season ticket renewal team. ' ||
        'Generate a concise, actionable win-back recommendation (3-4 sentences max) for this lapsed season ticket holder. ' ||
        'Be specific and direct. Include: (1) best contact method based on their history, ' ||
        '(2) one key talking point personalized to their situation, ' ||
        '(3) a specific offer angle or hook to re-engage them. ' ||
        'If they are a business account, leverage the business intelligence provided to craft a corporate hospitality or client entertainment pitch. ' ||
        'If objection was Bad Contact/No Response, suggest alternative contact strategies (email, LinkedIn, direct mail, different time of day). ' ||
        'If objection was Financial, suggest flexible payment plans or downsized package options. ' ||
        'If objection was Location/Stadium, acknowledge the exciting new ballpark plans and downtown St. Pete location. ' ||
        'If objection was Personal/Not Interested, suggest a lower-commitment re-entry (flex plan, mini-pack). ' ||
        'End with a realistic win probability: High/Medium/Low.' ||
        CHR(10) || CHR(10) ||
        'ACCOUNT PROFILE:' || CHR(10) ||
        '- Name: ' || COALESCE(e.contact_name, 'Unknown') ||
            CASE WHEN e.account_name IS NOT NULL THEN ' (' || e.account_name || ')' ELSE '' END || CHR(10) ||
        '- Renewal Amount: $' || e.renewal_amount::VARCHAR || CHR(10) ||
        '- Current Stage: ' || COALESCE(e.current_stage, 'Unknown') || CHR(10) ||
        '- Objection History: ' || COALESCE(e.objection_history, 'None recorded') || CHR(10) ||
        '- Lifetime Spend with Rays: ' ||
            CASE WHEN e.lifetime_spend IS NOT NULL AND e.lifetime_spend > 0
                 THEN '$' || ROUND(e.lifetime_spend, 0)::VARCHAR
                 ELSE 'No purchase history on file' END || CHR(10) ||
        '- Ticket Types Previously Purchased: ' || COALESCE(e.ticket_types, 'Unknown') || CHR(10) ||
        '- Seasons Active: ' || COALESCE(e.seasons_active, 'Unknown') || CHR(10) ||
        '- Last Email Sentiment: ' || COALESCE(e.last_email_sentiment, 'No emails on file') || CHR(10) ||
        '- Total Outreach Activities: ' || e.activity_count::VARCHAR || CHR(10) ||
        '- Account Type: ' || CASE WHEN e.is_business THEN 'Business/Corporate' ELSE 'Individual' END || CHR(10) ||
        '- Rep Notes: ' || COALESCE(NULLIF(e.notes, ''), 'None') ||
        CASE WHEN bi.business_intel IS NOT NULL
             THEN CHR(10) || '- BUSINESS INTELLIGENCE: ' || bi.business_intel
             ELSE '' END ||
        CHR(10) || CHR(10) ||
        'WIN-BACK RECOMMENDATION:'
    ) AS win_back_strategy
FROM TBRDP_DW_PROD.IM_RPT.TMP_RENEWAL_ENRICHED e
LEFT JOIN TBRDP_DW_PROD.IM_RPT.TMP_BUSINESS_INTEL bi
    ON LOWER(TRIM(e.account_name)) = LOWER(TRIM(bi.company_name));