INSERT INTO TBRDP_DW_PROD.IM_RPT.TMP_BUSINESS_INTEL VALUES
('Crisdel Group', 'Civil construction firm (highway, bridge, airport projects). ~200-500 employees, ~$88M revenue. NJ HQ with Tampa regional office at Palm River Rd. Expanding Florida operations. Tickets likely used for client entertainment with public-sector/GC clients in Tampa Bay infrastructure market.'),
('Fit2Run', 'Specialty running retail chain ("The Runner''s Superstore"). ~45 stores nationwide, HQ in Bradenton FL. Opened new Water Street Tampa store Dec 2025. CEO Parks Robinson actively expanding Tampa footprint. Natural fit for community engagement — pitch corporate hospitality tied to running events and ballpark activations.'),
('Dolman Law Group', 'Award-winning personal injury law firm, 8+ FL offices (Clearwater main). ~27 employees. Stan Gipe is head of litigation, lives in South Tampa. PI firms use sporting events heavily for client development and referral source entertainment.'),
('Cebert Wealth Management', 'Private wealth advisory, formerly Ameriprise. ~7 advisors managing ~$790M in assets. MAJOR NEWS: Team left Ameriprise for LPL Financial in Feb 2026. Re-establishing client relationships — season tickets are ideal client retention tool during this transition.'),
('Antinori Financial Group', 'Financial services/family office at 3217 S Dale Mabry, Tampa. Led by Anthony & Steven Antinori. Active FL corporation since 2008. Serves high-net-worth individuals — tickets likely used for client entertainment and relationship building.'),
('Window Craftsmen, Inc.', 'Custom replacement window/door manufacturer, family-owned since 1969 (3 generations). Based in Sarasota FL. Bob Detweiler is VP Operations. $28K spend suggests strong personal/family commitment. Appeal to family legacy and local roots.'),
('Murphy Auto Group Inc', 'Auto dealership group: 5 franchised dealerships + ~dozen support companies across FL, GA, SC. HQ at 3707 W Carmen St, Tampa. Filed new entity Oct 2024 suggesting expansion. Auto dealers use suites/premium seats for customer appreciation and sales incentives.'),
('Img Academy', 'Elite sports training facility and boarding school on 600+ acres in Bradenton. ~1,200-2,000 employees. Sold for $1.26B in 2023. Launching wrestling program 2026, hosting Under Armour Track Nationals. Paid $1.72M OFAC fine Feb 2026. Needs corporate entertainment for visiting families, coaches, and partners.'),
('Bridgestone Americas, Inc.', 'Subsidiary of Bridgestone Corp (Japan), one of world''s largest tire companies. ~$29B global revenue. Tampa facility at Joanne Kearney Blvd. Parent revenue declined 4.5% in 2024. Tickets likely used for regional client/employee entertainment at Tampa facility.'),
('Pricewaterhousecoopers Llp', 'Big Four professional services firm. ~328K employees globally, ~$53B revenue. Major Tampa office at 4040 W Boy Scout Blvd. EXPANDING: Signed long-term lease for 150K additional sq ft at MetWest Two — one of their biggest US office investments. Growing Tampa headcount — prime time for client entertainment and employee engagement.'),
('David P. Browne Pa', 'Estate planning/probate/trust law firm in Bonita Springs FL. AV Preeminent rated. Contact James Johnstone. Serves high-net-worth clients ideal for premium experiences. Despite SW FL location, $20K spend suggests strong personal connection.'),
('Focus Information Systems Llc', 'Direct-response marketing and lead gen for auto dealers. ~33 employees, ~$28M revenue. Tampa-based, CEO Raul Vazquez. Shares auto dealer client base with Murphy Auto Group. Tickets likely used to entertain dealer clients.'),
('35 Technologies Group', 'Defense/aeronautical electronic weapon systems manufacturer. ~30 employees, ~$3.5M revenue. HQ in Longwood FL (Orlando area). Owner Joe Norelli has 17 ventures including winery and vodka company. Philanthropist and community leader — appeal to networking and VIP experiences.'),
('Wilder Corporation', 'Real estate and property management (manufactured home communities). Based in Clearwater FL. Founder Maurice Wilder (passed 2019) was major Tampa Bay real estate mogul. Company continuing under professional management. Appeal to legacy and deep local history.'),
('Oxley & Brannon', 'Construction consulting (now OBCCI): scheduling, claims, dispute resolution since 1983. Based in St. Pete FL. Pat Brannon has 50+ years in FL construction, is a PE and CGC. Deeply embedded in Tampa Bay construction community — pitch relationship-building value in booming construction market.'),
('C-Ks Wholesale Produce Inc', 'Family-owned wholesale produce distributor for 30+ years. Located at Tampa Farmers Market (2801 E Hillsborough Ave). Supplies Tampa Bay restaurants and grocers. $19K spend suggests strong personal/family commitment. Appeal to local pride and restaurant industry connections.'),
('Grow Financial', 'Tampa-based federal credit union. ~587 employees, 291K members, $3.77B assets. 27 locations. EXPANDING: Moving to new HQ at GasWorx development. Won Top Workplaces awards. Record membership growth. Season tickets perfect for member appreciation and employee rewards.'),
('Big City Events, Llc', 'Event production company specializing in Tampa Bay festivals and concerts. Owner Ferdian Jap (USF grad, Stetson Law, UT MBA). Named Tampa Bay BJ Under-30 Up & Comers. Events company is natural fit — pitch cross-promotion between their festivals and Rays game-day experiences.'),
('Crowder Bros Hardware', 'Family-owned Ace Hardware franchise since 1955. Stores in St. Pete Beach, Spring Hill, Lakeland. Nearly 70-year Tampa Bay family business. Justin Crowder represents next generation. Appeal to family tradition and deep local community roots.'),
('Global Jet Sales', 'Private jet brokerage: aircraft sales and acquisitions. $7B+ in completed transactions. Based in St. Pete FL. Director Sasha Greve joined 2022. Caters to ultra-high-net-worth clients — premium/VIP experiences match their clientele expectations perfectly.'),
('Foot Locker', 'Global athletic retail (NYSE: FL). MAJOR CHANGE: Acquired by Dick''s Sporting Goods for $2.4B (Sept 2025). Planned St. Pete HQ relocation CANCELED Nov 2025. CEO replaced. Still has leased office space at 570 Carillon Pkwy. Contact may have changed post-acquisition — verify Jimmy Calhoun is still active before outreach.'),
('Guidant Legal Solutions', 'Legal consulting/mediation firm at 433 Central Ave, St. Pete. Jim Shea has 30+ years legal experience, former Chief Legal Officer. Mediates $100M+ construction disputes. High-value relationship for referrals and networking in legal/construction circles.'),
('Chadwell Supply', 'MRO distributor for multifamily property maintenance. ~2,500 employees, ~$91M revenue. HQ at Joanne Kearney Blvd, TAMPA. Opened Denver branch 2026, won Top Workplaces awards. At only $3,688 this account is MASSIVELY under-penetrated for a 2,500-employee Tampa HQ company. Major upsell opportunity.');
